package com.huy.enterprise.shipment; import com.huy.enterprise.common.enums.ShipmentStatus; import jakarta.validation.constraints.*; import java.time.LocalDate; import java.util.UUID; record ShipmentRequest(@NotBlank String shipmentCode,@NotNull UUID purchaseOrderId,String carrierName,LocalDate departureDate,LocalDate expectedArrivalDate,LocalDate actualArrivalDate,ShipmentStatus status,String currentLocation,String notes){} record ShipmentStatusRequest(@NotNull ShipmentStatus status){} record ShipmentResponse(UUID id,String shipmentCode,UUID purchaseOrderId,String carrierName,LocalDate departureDate,LocalDate expectedArrivalDate,LocalDate actualArrivalDate,ShipmentStatus status,String currentLocation,String notes){static ShipmentResponse from(Shipment s){return new ShipmentResponse(s.getId(),s.getShipmentCode(),s.getPurchaseOrder().getId(),s.getCarrierName(),s.getDepartureDate(),s.getExpectedArrivalDate(),s.getActualArrivalDate(),s.getStatus(),s.getCurrentLocation(),s.getNotes());}}
